  //           description: "The price of the bid made by the bidder."
  //         },
  //   ]
  //   return <Card.Group items={items} />;
  // };
  
  const renderCards = () => {
    const items = bids.map((bid) => {
      return {
        header: bid.bidAmount,
        description: bid.bid,
        fluid: true,
      };
    });
    return <Card.Group items={items} />;
  };


  // const renderCards = () => {
  //   const items = [
  //     {
  //       header: index,
  //       meta: "ID of the Bid",
  //       description:
  //         "The unique identification number of the given bid.",
  //       style: { overflowWrap: "break-word" }
  //     },
  //     {
  //       header: bidAmount,
  //       meta: "Bid Amount",
  //       description: "The price of the bid made by the bidder."
  //     },
  //     {
  //       header: description,
  //       meta: "Description",
  //       description:
  //         "Proposal of the bidder."
  //     }
  //   ];
  //   return <Card.Group items={items} />;
  // };


  return (
    <Layout>
      <h3>Bid Show</h3>
      <Grid>
        <Grid.Row>
          <Grid.Column width={10}>{renderCards()}</Grid.Column>
          <Grid.Column width={6}></Grid.Column>
        </Grid.Row>
        <Grid.Row>
          <Grid.Column>
            <Link route={`/tenders/${address}`}>
              <a>
                <Button primary>Details of the tender.</Button>
              </a>
            </Link>
          </Grid.Column>
        </Grid.Row>
      </Grid>
    </Layout>
  );
};

