  var i;
  for(i = 0; i < numberOfBids; i++)
  {
    const bid = await tender.methods.publicBids(i).call();
    bids.push(JSON.stringify(bid))
  }
  // const bids = [...new Array(numberOfBids)].map(async (num, index) => {
